  "controller": "{\n  \"schemaRevision\": \"patch-map-conformance/1\",\n  \"id\": \"controller\",\n  \"description\": \"Public argument failures, lifecycle replacement, keyed presentation, viewport, rotation and transform sessions. Semantic traces only; visual/input integration remains separate.\",\n  \"surface\": {\n    \"width\": 480,\n    \"height\": 520,\n    \"pixelRatio\": 1,\n    \"background\": \"#f8fafc\"\n  },\n  \"dataset\": [\n    {\n      \"type\": \"rect\",\n      \"id\": \"rect\",\n      \"attrs\": {\n        \"x\": 10,\n        \"y\": 20\n      },\n      \"size\": {\n        \"width\": 40,\n        \"height\": 30\n      },\n      \"fill\": \"#2563eb\"\n    },\n    {\n      \"type\": \"item\",\n      \"id\": \"item\",\n      \"attrs\": {\n        \"x\": 100,\n        \"y\": 20\n      },\n      \"size\": {\n        \"width\": 40,\n        \"height\": 80\n      },\n      \"components\": [\n        {\n          \"type\": \"bar\",\n          \"id\": \"bar\",\n          \"size\": {\n            \"width\": 20,\n            \"height\": 30\n          },\n          \"source\": {\n            \"type\": \"rect\"\n          },\n          \"animation\": false\n        }\n      ]\n    }\n  ],\n  \"commands\": [\n    {\n      \"id\": \"bar-scope\",\n      \"op\": \"targets.query\",\n      \"input\": {\n        \"type\": \"bar\"\n      }\n    },\n    {\n      \"id\": \"empty-query\",\n      \"op\": \"targets.query\",\n      \"input\": {\n        \"id\": \"absent\"\n      }\n    },\n    {\n      \"id\": \"missing-get\",\n      \"op\": \"targets.get\",\n      \"input\": {\n        \"id\": \"absent\"\n      }\n    },\n    {\n      \"id\": \"empty-batch\",\n      \"op\": \"updateBatch\",\n      \"input\": {\n        \"targets\": [],\n        \"bar\": {\n          \"height\": []\n        }\n      },\n      \"expect\": {\n        \"status\": \"unchanged\",\n        \"snapshotUnchanged\": true\n      }\n    },\n    {\n      \"id\": \"duplicate-batch\",\n      \"op\": \"updateBatch\",\n      \"input\": {\n        \"targets\": [\n          \"item\",\n          \"item\"\n        ],\n        \"bar\": {\n          \"height\": [\n            10,\n            20\n          ]\n        }\n      },\n      \"expect\": {\n        \"status\": \"rejected\",\n        \"snapshotUnchanged\": true\n      }\n    },\n    {\n      \"id\": \"unequal-batch\",\n      \"op\": \"updateBatch\",\n      \"input\": {\n        \"targets\": [\n          \"item\"\n        ],\n        \"bar\": {\n          \"height\": [\n            10,\n            20\n          ]\n        }\n      },\n      \"expect\": {\n        \"throws\": {\n          \"kind\": \"invalid-argument\"\n        },\n        \"snapshotUnchanged\": true\n      }\n    },\n    {\n      \"id\": \"alpha-layer\",\n      \"op\": \"presentation.set\",\n      \"input\": {\n        \"key\": \"dim\",\n        \"layer\": {\n          \"targets\": [\n            {\n              \"id\": \"item\",\n              \"componentId\": \"bar\"\n            }\n          ],\n          \"matched\": {\n            \"alphaMultiplier\": 0.5\n          }\n        }\n      },\n      \"expect\": {\n        \"semanticHashUnchanged\": true,\n        \"historyUnchanged\": true\n      },\n      \"refs\": {\n        \"scope\": \"bar-scope\"\n      }\n    },\n    {\n      \"id\": \"alpha-clear\",\n      \"op\": \"presentation.clear\",\n      \"input\": \"dim\",\n      \"expect\": {\n        \"semanticHashUnchanged\": true,\n        \"historyUnchanged\": true\n      }\n    },\n    {\n      \"id\": \"alpha-clear-again\",\n      \"op\": \"presentation.clear\",\n      \"input\": \"dim\"\n    },\n    {\n      \"id\": \"authored-change\",\n      \"op\": \"update\",\n      \"input\": {\n        \"id\": \"item\",\n        \"bar\": {\n          \"height\": 40\n        }\n      },\n      \"expect\": {\n        \"status\": \"committed\"\n      }\n    },\n    {\n      \"id\": \"stale-target\",\n      \"op\": \"updateBatch\",\n      \"input\": {\n   