\n            \"x\": 10,\n            \"y\": 20\n          },\n          \"size\": {\n            \"width\": 40,\n            \"height\": 30\n          },\n          \"fill\": \"#2563eb\"\n        },\n        {\n          \"type\": \"item\",\n          \"id\": \"item\",\n          \"attrs\": {\n            \"x\": 100,\n            \"y\": 20\n          },\n          \"size\": {\n            \"width\": 40,\n            \"height\": 80\n          },\n          \"components\": [\n            {\n              \"type\": \"bar\",\n              \"id\": \"bar\",\n              \"size\": {\n                \"width\": 20,\n                \"height\": 30\n              },\n              \"source\": {\n                \"type\": \"rect\"\n              },\n              \"animation\": false\n            }\n          ]\n        }\n      ]\n    },\n    {\n      \"id\": \"restored-history-empty\",\n      \"op\": \"history.undo\",\n      \"expect\": {\n        \"status\": \"unavailable\"\n      }\n    },\n    {\n      \"id\": \"replace-fit-options\",\n      \"op\": \"data.replace\",\n      \"input\": [\n        {\n          \"type\": \"rect\",\n          \"id\": \"rect\",\n          \"attrs\": {\n            \"x\": 10,\n            \"y\": 20\n          },\n          \"size\": {\n            \"width\": 40,\n            \"height\": 30\n          },\n          \"fill\": \"#2563eb\"\n        },\n        {\n          \"type\": \"item\",\n          \"id\": \"item\",\n          \"attrs\": {\n            \"x\": 100,\n            \"y\": 20\n          },\n          \"size\": {\n            \"width\": 40,\n            \"height\": 80\n          },\n          \"components\": [\n            {\n              \"type\": \"bar\",\n              \"id\": \"bar\",\n              \"size\": {\n                \"width\": 20,\n                \"height\": 30\n              },\n              \"source\": {\n                \"type\": \"rect\"\n              },\n              \"animation\": false\n            }\n