  "editor-lifecycle": "{\n  \"schemaRevision\": \"patch-map-conformance/1\",\n  \"id\": \"editor-lifecycle\",\n  \"description\": \"Named relation conflicts/removal, text recovery/cancel/delete, mode replacement, and host-confirmed cascade delete public workflows.\",\n  \"surface\": {\n    \"width\": 480,\n    \"height\": 520,\n    \"pixelRatio\": 1,\n    \"background\": \"#f8fafc\"\n  },\n  \"dataset\": [\n    {\n      \"type\": \"rect\",\n      \"id\": \"a\",\n      \"attrs\": {\n        \"x\": 10,\n        \"y\": 10\n      },\n      \"size\": {\n        \"width\": 40,\n        \"height\": 30\n      }\n    },\n    {\n      \"type\": \"rect\",\n      \"id\": \"b\",\n      \"attrs\": {\n        \"x\": 90,\n        \"y\": 10\n      },\n      \"size\": {\n        \"width\": 40,\n        \"height\": 30\n      }\n    },\n    {\n      \"type\": \"relations\",\n      \"id\": \"rel\",\n      \"links\": [\n        {\n          \"source\": \"a\",\n          \"target\": \"b\"\n        }\n      ]\n    },\n    {\n      \"type\": \"text\",\n      \"id\": \"text\",\n      \"text\": \"Original 한글\",\n      \"size\": {\n        \"width\": 160,\n        \"height\": 40\n      },\n      \"style\": {\n        \"fontSize\": 16,\n        \"fill\": \"#123456\"\n      }\n    },\n    {\n      \"type\": \"grid\",\n      \"id\": \"grid\",\n      \"attrs\": {\n        \"y\": 100\n      },\n      \"cells\": [\n        [\n          1,\n          0\n        ]\n      ],\n      \"item\": {\n        \"size\": {\n          \"width\": 20,\n          \"height\": 20\n        },\n        \"components\": []\n      }\n    }\n  ],\n  \"commands\": [\n    {\n      \"id\": \"relation-enter\",\n      \"op\": \"editor.execute\",\n      \"input\": {\n        \"type\": \"enter-relation-edit\",\n        \"target\": \"rel\"\n      },\n      \"expect\": {\n        \"status\": \"committed\"\n      }\n    },\n    {\n      \"id\": \"relation-duplicate\",\n      \"op\": \"editor.execute\",\n      \"input\": {\n        \