d\"\n      }\n    },\n    {\n      \"id\": \"relation-exit-empty\",\n      \"op\": \"editor.execute\",\n      \"input\": {\n        \"type\": \"exit-relation-edit\",\n        \"relationId\": \"rel\"\n      },\n      \"expect\": {\n        \"status\": \"committed\"\n      }\n    },\n    {\n      \"id\": \"relation-undo\",\n      \"op\": \"history.undo\",\n      \"expect\": {\n        \"status\": \"committed\"\n      }\n    },\n    {\n      \"id\": \"text-open-cancel\",\n      \"op\": \"editor.execute\",\n      \"input\": {\n        \"type\": \"open-text-editor\",\n        \"target\": \"text\",\n        \"hostOverlay\": true\n      },\n      \"expect\": {\n        \"status\": \"committed\"\n      }\n    },\n    {\n      \"id\": \"text-cancel\",\n      \"op\": \"editor.execute\",\n      \"input\": {\n        \"type\": \"cancel-text-edit\",\n        \"target\": \"text\"\n      },\n      \"expect\": {\n        \"status\": \"committed\"\n      }\n    },\n    {\n      \"id\": \"text-open-unchanged\",\n      \"op\": \"editor.execute\",\n      \"input\": {\n        \"type\": \"open-text-editor\",\n        \"target\": \"text\",\n        \"hostOverlay\": true\n      },\n      \"expect\": {\n        \"status\": \"committed\"\n      }\n    },\n    {\n      \"id\": \"text-unchanged\",\n      \"op\": \"editor.execute\",\n      \"input\": {\n        \"type\": \"commit-text-edit\",\n        \"target\": \"text\",\n        \"text\": \"Original 한글\",\n        \"actionId\": \"same\"\n      },\n      \"expect\": {\n        \"status\": \"unchanged\"\n      }\n    },\n    {\n      \"id\": \"text-open-replace\",\n      \"op\": \"editor.execute\",\n      \"input\": {\n        \"type\": \"open-text-editor\",\n        \"target\": \"text\",\n        \"hostOverlay\": true\n      },\n      \"expect\": {\n        \"status\": \"committed\"\n      }\n    },\n    {\n      \"id\": \"replace-while-text-open\",\n      \"op\": \"data.replace\",\n      \"input\": [\n        {\n          \"type\": \"rect\"