  "transform-geometry": "{\n  \"schemaRevision\": \"patch-map-conformance/1\",\n  \"id\": \"transform-geometry\",\n  \"description\": \"Nested affine transform, multi-target resize/rotation and session validation through the public binding.\",\n  \"surface\": {\n    \"width\": 480,\n    \"height\": 520,\n    \"pixelRatio\": 1,\n    \"background\": \"#f8fafc\"\n  },\n  \"dataset\": [\n    {\n      \"type\": \"group\",\n      \"id\": \"group\",\n      \"attrs\": {\n        \"x\": 100,\n        \"y\": 120,\n        \"angle\": 30,\n        \"scaleX\": -2\n      },\n      \"children\": [\n        {\n          \"type\": \"rect\",\n          \"id\": \"a\",\n          \"attrs\": {\n            \"x\": 10,\n            \"y\": 20,\n            \"rotation\": 0.2\n          },\n          \"size\": {\n            \"width\": 40,\n            \"height\": 30\n          },\n          \"fill\": \"#2563eb\"\n        },\n        {\n          \"type\": \"rect\",\n          \"id\": \"b\",\n          \"attrs\": {\n            \"x\": 100,\n            \"y\": 20\n          },\n          \"size\": {\n            \"width\": 20,\n            \"height\": 50\n          },\n          \"fill\": \"#22c55e\"\n        }\n      ]\n    },\n    {\n      \"type\": \"rect\",\n      \"id\": \"locked\",\n      \"locked\": true,\n      \"attrs\": {\n        \"x\": 250,\n        \"y\": 50\n      },\n      \"size\": {\n        \"width\": 30,\n        \"height\": 20\n      }\n    },\n    {\n      \"type\": \"rect\",\n      \"id\": \"free\",\n      \"attrs\": {\n        \"x\": 200,\n        \"y\": 130\n      },\n      \"size\": {\n        \"width\": 40,\n        \"height\": 60\n      }\n    }\n  ],\n  \"commands\": [\n    {\n      \"id\": \"nested-move\",\n      \"op\": \"transform.moveBy\",\n      \"input\": {\n        \"targets\": [\n          \"a\"\n        ],\n        \"delta\": [\n          7.5,\n          -2.5\n        ]\n      },\n      \"expect\": {\n        \"status\": \"committed\"\n      }\n    },\n   