e\",\n          \"input\": {\n            \"id\": \"text\",\n            \"changes\": {\n              \"text\": \"한글 é 👨‍👩‍👧‍👦 👍🏽 🇰🇷\",\n              \"size\": {\n                \"width\": 210,\n                \"height\": 90\n              },\n              \"style\": {\n                \"fontSize\": 18,\n                \"wordWrap\": true,\n                \"breakWords\": true,\n                \"wordWrapWidth\": 200\n              }\n            }\n          },\n          \"expect\": {\n            \"status\": \"committed\"\n          }\n        },\n        {\n          \"id\": \"양방향 문자\",\n          \"op\": \"update\",\n          \"input\": {\n            \"id\": \"text\",\n            \"changes\": {\n              \"text\": \"Hello مرحبا שלום 123\",\n              \"size\": {\n                \"width\": 210,\n                \"height\": 90\n              },\n              \"style\": {\n                \"fontSize\": 18,\n                \"wordWrap\": true,\n                \"breakWords\": true,\n                \"wordWrapWidth\": 200\n              }\n            }\n          },\n          \"expect\": {\n            \"status\": \"committed\"\n          }\n        },\n        {\n          \"id\": \"줄바꿈·넘침\",\n          \"op\": \"update\",\n          \"input\": {\n            \"id\": \"text\",\n            \"changes\": {\n              \"text\": \"첫 번째 줄\\n두 번째 긴 줄 가나다 ABCDEFGHIJKLMNOP\\n세 번째 줄\",\n              \"size\": {\n                \"width\": 210,\n                \"height\": 90\n              },\n              \"style\": {\n                \"fontSize\": 18,\n                \"wordWrap\": true,\n                \"breakWords\": true,\n                \"wordWrapWidth\": 200\n              }\n            }\n          },\n          \"expect\": {\n            \"status\": \"committed\"\n          }\n        },\n        {\n          \"id\": \"자동 글자 크기\",\n          \"op\": \"update\",\n          \"input\": {\n            \"id\": \"grid.0.0\",\n            \"text\": {\n              \"componentId\": \"label\",\n              \"changes\": {\n                \"style\": {\n                  \"fontSize\": \"auto\",\n                  \"autoFont\": {\n                    \"min\": 8,\n                    \"max\": 24\n                  }\n                }\n              },\n              \"text\": \"긴 텍스트 😀\"\n            }\n          },\n          \"expect\": {\n            \"status\": \"committed\"\n          }\n        },\n        {\n          \"id\": \"Undo\",\n          \"op\": \"history.undo\"\n        },\n        {\n          \"id\": \"Redo\",\n          \"op\": \"history.redo\"\n        }\n      ],\n      \"kind\": \"regression\"\n    },\n    {\n      \"id\": \"input\",\n      \"title\": \"회귀 · 선택·포인터·제스처\",\n      \"fixture\": \"gallery\",\n      \"hint\": \"탭·더블탭·빈 영역, 길게 누르기(웹 우클릭), pinch(웹 휠)를 시험하세요. 박스 선택 스위치를 켜면 드래그로 선택합니다. pointer와 selection 상태를 확인하세요.\",\n      \"kind\": \"regression\"\n    },\n    {\n      \"id\": \"lifecycle\",\n      \"title\": \"회귀 · 캡처·생성·해제\",\n      \"fixture\": \"gallery\",\n      \"hint\": \"캡처, 빈 데이터, 뷰 분리/재연결, 두 번째 맵, 재생성을 시험하세요. 앱을 홈으로 보냈다가 복귀해 회전·입력이 계속 동작하는지도 확인하세요.\",\n      \"kind\": \"regression\"\n    },\n    {\n      \"id\": \"accessibility\",\n      \"title\": \"회귀 · 접근성·모션 감소\",\n      \"fixture\": \"gallery\",\n      \"hint\": \"기기 VoiceOver/TalkBack을 켜고 요소 이동·활성화·선택을 확인하세요. OS의 모션 감소 설정 후 회전을 실행하세요. 웹은 Tab/Enter와 브라우저 모션 감소 설정을 사용하세요.\",\n      \"kind\": \"regression\"\n    }\n  ]\n}\n",
